<?php
declare(strict_types=1);
namespace App\Command;
use App\Imperium\Runtime\Imperator\ProfileApprovalDecisionService;
use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Input\InputOption;use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:imperator:decide-profile-approval',description:'Seal the Imperator decision for one exact Senate-examined Profile.')]
final class ImperatorDecideProfileApprovalCommand extends Command{public function __construct(private readonly ProfileApprovalDecisionService$s){parent::__construct();}protected function configure():void{$this->addArgument('senate-disposition-id',InputArgument::REQUIRED)->addArgument('disposition',InputArgument::REQUIRED)->addArgument('response',InputArgument::REQUIRED)->addArgument('limitations',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->s->decide((string)$i->getArgument('senate-disposition-id'),(string)$i->getArgument('disposition'),(string)$i->getArgument('response'),(string)$i->getArgument('limitations'));}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}$o->writeln($i->getOption('json')?json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR):'<info>IMPERATOR_PROFILE_DECISION_SEALED</info> '.$r['decision_id']);return self::SUCCESS;}}
